"""Evaluate research requests against supplied evidence and policy."""

import json


def _result(status, value, sources, unknowns):
    return {
        "status": status,
        "value": value,
        "sources": sources,
        "unknowns": unknowns,
    }


def _canonical(value):
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request, evidence, policy):
    """Evaluate a request without modifying any supplied input."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return _result("unknown", None, [], missing)

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and not record.get("verified", False):
            continue

        record_conditions = record.get("conditions", {})
        if any(
            name not in record_conditions
            or record_conditions[name] != request_conditions[name]
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = set()
    for record in eligible:
        targets = record.get("supersedes", [])
        if isinstance(targets, str):
            targets = [targets]
        if isinstance(targets, list):
            superseded.update(targets)
    eligible = [
        record for record in eligible
        if record.get("source") not in superseded
    ]

    if not eligible:
        return _result("unknown", None, [], ["no matching evidence"])

    sources = sorted(record["source"] for record in eligible)
    values = {}
    for record in eligible:
        value = record.get("value")
        values.setdefault(_canonical(value), value)

    if len(values) != 1:
        return _result("conflict", None, sources, ["source disagreement"])

    value = next(iter(values.values()))
    status = "unsupported" if value is False else "supported"
    return _result(status, value, sources, [])

